struct PermissionTracker {
    var isAuthorized: Bool
    var isRestricted: Bool

    var shouldOpenSettings: Bool {
        !isAuthorized && !isRestricted
    }
}

let tracker = PermissionTracker(isAuthorized: false, isRestricted: false)
print("Open settings: \(tracker.shouldOpenSettings)")

enum AuthState {
    case notDetermined
    case authorized
    case denied
    case restricted
}

func message(for state: AuthState) -> String {
    switch state {
    case .notDetermined:
        return "ask permission"
    case .authorized:
        return "access granted"
    case .denied:
        return "open settings"
    case .restricted:
        return "feature locked"
    }
}

print("State result: \(message(for: .authorized))")

